import { ErasureRepository, type ErasureRequestRow } from './erasure-repository.js';
import { CustomerRepository } from './repository.js';

function toResponse(row: ErasureRequestRow) {
  return {
    id: row.id,
    customerId: row.customer_id,
    status: row.status,
    attempts: row.attempts,
    createdAt: row.created_at.toISOString(),
    updatedAt: row.updated_at.toISOString(),
    completedAt: row.completed_at?.toISOString() ?? null,
    lastError: row.last_error,
  };
}

export class ErasureService {
  private readonly repository = new ErasureRepository();
  private readonly customerRepository = new CustomerRepository();

  async requestErasure(
    client: pg.PoolClient,
    merchantId: string,
    customerId: string,
    idempotencyKey: string,
    hash: string,
  ): Promise<Record<string, unknown> | { conflict: string }> {
    // Validate customer exists and belongs to merchant
    const customer = await this.customerRepository.find(merchantId, customerId);
    if (!customer) throw Object.assign(new Error('customer not found'), { statusCode: 404 });

    // Check for existing erasure request for this customer
    const existing = await this.repository.findExisting(merchantId, customerId);
    if (existing) {
      // If the existing request is for the same customer, return it (even for a new idempotency key)
      await this.repository.saveIdempotency(client, merchantId, 'erasure-request', idempotencyKey, hash, 202, toResponse(existing));
      return toResponse(existing);
    }

    // Check if this idempotency key was already used for a different customer
    // (This is handled by the conflict check in the calling code)

    const erasure = await this.repository.create(client, merchantId, customerId);
    const response = toResponse(erasure);

    // Save the idempotency response
    await this.repository.saveIdempotency(client, merchantId, 'erasure-request', idempotencyKey, hash, 202, response);

    return response;
  }

  async findByIdempotency(
    client: pg.PoolClient,
    merchantId: string,
    customerId: string,
    idempotencyKey: string,
    hash: string,
  ): Promise<Record<string, unknown> | { conflict: string } | undefined> {
    const idempotency = await this.repository.findIdempotency(client, merchantId, 'erasure-request', idempotencyKey);
    if (!idempotency) return undefined;

    // Reusing idempotency key for a different customer: 409
    const body = idempotency.response_body as Record<string, unknown> | null;
    if (body && body.customerId !== customerId) {
      return { conflict: 'idempotency_key_reused_for_different_customer' };
    }

    return body ?? undefined;
  }

  async getStatus(merchantId: string, requestId: string): Promise<Record<string, unknown> | undefined> {
    const row = await this.repository.findById(merchantId, requestId);
    if (!row) return undefined;
    return toResponse(row);
  }
}"}

