import { EVENT_TYPES } from '../../../packages/contracts/src/events.js';
import { pool, transaction } from '../../../packages/database/src/pool.js';
import { addOutboxEvent } from '../../../packages/messaging/src/outbox.js';
import { startOutboxPublisher } from '../../../packages/messaging/src/publisher.js';
import { logger } from '../../../packages/observability/src/logger.js';
import { CUSTOMER_INDEX, searchClient } from '../../../packages/search/src/client.js';
import { PrivacyRepository } from './repository.js';

process.env.SERVICE_NAME = 'privacy-worker';
const repository = new PrivacyRepository();
const controller = new AbortController();

async function executeErasure(client: import('pg').PoolClient, job: { id: string; merchant_id: string; customer_id: string }): Promise<void> {
  // Verify customer exists
  const customer = await repository.readCustomer(client, job.merchant_id, job.customer_id);
  if (!customer) {
    // Customer already gone
    await repository.markCompleted(client, job.id);
    return;
  }

  // 1. Delete/redact customer PII
  await repository.deleteAddresses(client, job.merchant_id, job.customer_id);
  await repository.deleteContacts(client, job.merchant_id, job.customer_id);
  await repository.deletePaymentMethods(client, job.merchant_id, job.customer_id);
  await repository.deleteProviderCustomerMappings(client, job.merchant_id, job.customer_id);
  await repository.deleteSupportData(client, job.merchant_id, job.customer_id);
  await repository.deleteNotificationPreferences(client, job.merchant_id, job.customer_id);

  // 2. Anonymize financial records that must be retained
  await repository.anonymizePaymentIntents(client, job.merchant_id, job.customer_id);
  await repository.anonymizeInvoiceSnapshots(client, job.merchant_id, job.customer_id);
  await repository.anonymizeRefundEmails(client, job.merchant_id, job.customer_id);
  await repository.anonymizeProviderSandboxCustomers(client, job.merchant_id, job.customer_id);

  // 3. Anonymize operational records
  await repository.anonymizeNotifications(client, job.merchant_id, job.customer_id);
  await repository.anonymizeEmailDeliveries(client, job.merchant_id, job.customer_id);
  await repository.anonymizeAnalyticsEvents(client, job.merchant_id, job.customer_id);
  await repository.anonymizeDocumentManifests(client, job.merchant_id, job.customer_id);

  // 4. Anonymize the customer record itself
  await repository.anonymizeCustomer(client, job.merchant_id, job.customer_id);

  // 5. Remove from search index and Redis cache
  try {
    await searchClient.delete({ index: CUSTOMER_INDEX, id: `${job.merchant_id}:${job.customer_id}` });
  } catch { /* index may not exist yet */ }

  // 6. Emit deletion event
  await addOutboxEvent(client, {
    eventType: EVENT_TYPES.CUSTOMER_DELETED,
    aggregateType: 'customer',
    aggregateId: job.customer_id,
    merchantId: job.merchant_id,
    correlationId: uuid(),
    payload: { customerId: job.customer_id },
  });

  // 7. Mark as completed
  await repository.markCompleted(client, job.id);
}

async function processOne(): Promise<boolean> {
  return transaction(async (client) => {
    const job = await repository.claimPending(client);
    if (!job) return false;
    try {
      await executeErasure(client, job);
    } catch (error) {
      const message = error instanceof Error ? error.message.slice(0, 300) : String(error).slice(0, 300);
      logger.error({ error: message, erasureRequestId: job.id }, 'erasure job failed');
      await repository.markFailed(client, job.id, message);
    }
    return true;
  }).catch((error) => {
    logger.error({ error }, 'erasure transaction failed');
    return false;
  });
}

async function run(signal: AbortSignal): Promise<void> {
  while (!signal.aborted) {
    const processed = await processOne();
    await new Promise((resolve) => setTimeout(resolve, processed ? 50 : 500));
  }
}

void startOutboxPublisher(controller.signal);
void run(controller.signal);
logger.info('privacy worker started');
for (const signal of ['SIGTERM', 'SIGINT'] as const) process.on(signal, () => controller.abort());"}

